using System;using System.Linq;using Mono.Cecil;
class Verifier {
 static void Main(string[] a){using var game=AssemblyDefinition.ReadAssembly(a[0]);using var mod=AssemblyDefinition.ReadAssembly(a[1]);int n=0;
  void Check(bool b,string s){if(!b)throw new Exception(s);n++;Console.WriteLine("PASS "+s);}
  foreach(var t in mod.MainModule.Types.SelectMany(t=>t.NestedTypes))foreach(var attr in t.CustomAttributes.Where(x=>x.AttributeType.Name=="HarmonyPatch")){
   var type=((TypeReference)attr.ConstructorArguments[0].Value).FullName;var method=(string)attr.ConstructorArguments[1].Value;var target=game.MainModule.Types.Single(x=>x.FullName==type).Methods.Where(x=>x.Name==method).ToArray();Check(target.Length==1,"real unambiguous patch "+type+"."+method);
   foreach(var hook in t.Methods.Where(x=>x.CustomAttributes.Any(y=>y.AttributeType.Name=="HarmonyPrefix"||y.AttributeType.Name=="HarmonyPostfix"||y.AttributeType.Name=="HarmonyFinalizer")))foreach(var p in hook.Parameters.Where(x=>!x.Name.StartsWith("__")))Check(target[0].Parameters.Any(x=>x.Name==p.Name&&x.ParameterType.FullName==p.ParameterType.FullName),"real injected argument "+p.Name);
  }
  foreach(var s in new[]{("SE_Shield","m_totalAbsorbDamage"),("SE_Shield","m_damage"),("StatusEffect","m_time"),("StatusEffect","m_character"),("Character","m_body"),("Character","m_maxAirAltitude"),("SEMan","m_character")})Check(game.MainModule.Types.Single(x=>x.Name==s.Item1).Fields.Any(x=>x.Name==s.Item2),"real private field "+s.Item1+"."+s.Item2);
  foreach(var s in new[]{("StatusEffect","m_startEffectInstances"),("EnemyHud","m_huds"),("EnemyHud","m_hudRoot"),("EnemyHud","m_baseHud")})Check(game.MainModule.Types.Single(x=>x.Name==s.Item1).Fields.Any(x=>x.Name==s.Item2),"real presentation field "+s.Item1+"."+s.Item2);
  Check(game.MainModule.Types.Single(x=>x.Name=="StatusEffect").Methods.Any(x=>x.Name=="TriggerStartEffects"&&x.Parameters.Count==0),"real native visual recreation method");
  Check(game.MainModule.Types.Single(x=>x.Name=="BaseAI").Methods.Count(x=>x.Name=="MoveTo"&&x.Parameters.Count==4)==1,"real native idle movement API");
  foreach(var name in new[]{"m_healthBarRoot","m_rootObject","m_healthBarFast","m_healthBarSlow","m_healthText","m_gpRoot","m_gpName","m_gpCooldown","m_gpIcon"})Check(game.MainModule.Types.Single(x=>x.Name=="Hud").Fields.Any(x=>x.Name==name),"real player HUD field "+name);
  foreach(var name in new[]{"m_speed","m_runSpeed"})Check(game.MainModule.Types.Single(x=>x.Name=="Character").Fields.Any(x=>x.Name==name&&x.FieldType.FullName=="System.Single"),"real catch-up speed field "+name);
  var area=game.MainModule.Types.Single(x=>x.Name=="Aoe");Check(area.Fields.Any(x=>x.Name=="m_radius"&&x.FieldType.FullName=="System.Single"),"real native Aoe radius field");
  Check(area.Methods.Single(x=>x.Name=="FindHits").Body.Instructions.Select(x=>x.Operand).OfType<MethodReference>().Any(x=>x.Name=="OverlapSphereNonAlloc"),"real native area query uses world-space sphere overlap");
  var range=mod.MainModule.Types.Single(x=>x.Name=="ProtectionRange");var writes=range.Methods.Where(x=>x.HasBody).SelectMany(x=>x.Body.Instructions).Where(x=>x.OpCode.Code==Mono.Cecil.Cil.Code.Stfld).Select(x=>x.Operand).OfType<FieldReference>().ToArray();Check(writes.Length==1&&writes[0].DeclaringType.FullName=="Aoe"&&writes[0].Name=="m_radius","range patch writes only native area radius, not damage or targeting fields");
  var seman=game.MainModule.Types.Single(x=>x.Name=="SEMan");var internalAdd=seman.Methods.Single(x=>x.Name=="Internal_AddStatusEffect");var directAdd=seman.Methods.Single(x=>x.Name=="AddStatusEffect"&&x.Parameters[0].ParameterType.FullName=="StatusEffect");
  foreach(var refreshMethod in new[]{internalAdd,directAdd}){var nativeCalls=refreshMethod.Body.Instructions.Select(x=>x.Operand).OfType<MethodReference>().Select(x=>x.Name).ToArray();Check(Array.IndexOf(nativeCalls,"ResetTime")>=0&&Array.IndexOf(nativeCalls,"SetLevel")>Array.IndexOf(nativeCalls,"ResetTime"),"real native refresh path reaches shared reset and level hooks: "+refreshMethod.FullName);}
  Check(!game.MainModule.Types.Single(x=>x.Name=="SE_Shield").Methods.Any(x=>x.Name=="ResetTime"),"native shield inherits the patched shared timer-reset method");
  var character=game.MainModule.GetType("Character");
  var landing=character.Methods.Single(x=>x.Name=="UpdateGroundContact").Body.Instructions;
  Check(landing.Any(x=>x.Operand is FieldReference f&&f.DeclaringType.Name=="DamageTypes"&&f.Name=="m_damage")
   &&landing.Any(x=>x.Operand is MethodReference m&&m.Name=="Damage"),"real landing sends pure damage through Character.Damage");
  var hitType=game.MainModule.GetType("HitData").NestedTypes.Single(x=>x.Name=="HitType");
  Check(hitType.Fields.Any(x=>x.Name=="Fall"),"real hit type distinguishes falls from other damage");
  var shieldHit=game.MainModule.GetType("SE_Shield").Methods.Single(x=>x.Name=="OnDamaged").Body.Instructions;
  Check(shieldHit.Any(x=>x.Operand is MethodReference m&&m.Name=="GetTotalDamage")
   &&shieldHit.Any(x=>x.Operand is MethodReference m&&m.Name=="ApplyModifier"),"native shield counts the raw fall before zeroing its blockable channels");
  var hitModifier=game.MainModule.GetType("HitData").Methods.Single(x=>x.Name=="ApplyModifier"&&x.Parameters.Count==1&&x.Parameters[0].ParameterType.Name=="Single");
  Check(!hitModifier.Body.Instructions.Any(x=>x.OpCode.Code==Mono.Cecil.Cil.Code.Stfld&&x.Operand is FieldReference f&&f.Name=="m_damage"),"native hit modifier preserves pure damage");
  var directHit=game.MainModule.Types.Single(x=>x.Name=="Character").Methods.Single(x=>x.Name=="RPC_Damage");var directCalls=directHit.Body.Instructions.Select(x=>x.Operand).OfType<MethodReference>().Select(x=>x.Name).ToArray();Check(Array.IndexOf(directCalls,"ResetTime")>=0&&Array.IndexOf(directCalls,"SetLevel")>Array.IndexOf(directCalls,"ResetTime"),"real Character.RPC_Damage refreshes existing shield directly, bypassing SEMan insertion hooks");
  Check(game.MainModule.Types.Single(x=>x.Name=="Character").Fields.Any(x=>x.Name=="m_regenAllHPTime"&&x.FieldType.FullName=="System.Single"),"real native full-health regeneration time field");
  Check(game.MainModule.Types.Single(x=>x.Name=="Player").Methods.Any(x=>x.Name=="GetFoods"&&x.Parameters.Count==0),"real player food regeneration inputs");
  Check(seman.Methods.Any(x=>x.Name=="ModifyHealthRegen"&&x.Parameters[0].ParameterType.IsByReference),"real player health regeneration modifiers");
  Check(game.MainModule.Types.Single(x=>x.Name=="EnemyHud").Methods.Single(x=>x.Name=="ShowHud").Parameters.Select(x=>x.Name).SequenceEqual(new[]{"c","isMount"}),"real local overhead HUD creation method");
  Check(game.MainModule.Types.Single(x=>x.Name=="BaseAI").Fields.Any(x=>x.Name=="m_tamable"&&x.FieldType.FullName=="Tameable"),"real native animal hunger reference available for scoped summon recovery");
  var regeneration=game.MainModule.Types.Single(x=>x.Name=="BaseAI").Methods.Single(x=>x.Name=="UpdateRegeneration");var regenCalls=regeneration.Body.Instructions.Select(x=>x.Operand).OfType<MethodReference>().Select(x=>x.Name).ToArray();Check(regenCalls.Contains("IsHungry")&&regenCalls.Contains("GetWorldTimeDelta")&&regenCalls.Contains("Heal"),"real regeneration retains native hunger gate, world-time tick and healing call");
  Check(game.MainModule.Types.Single(x=>x.Name=="Tameable").Methods.Any(x=>x.Name=="IsHungry"&&x.Parameters.Count==0),"real animal hunger method exists");
  Check(game.MainModule.Types.Single(x=>x.Name=="StatusEffect").Fields.Any(x=>x.Name=="m_ttl"&&x.FieldType.FullName=="System.Single"),"real shield duration field for countdown");Check(game.MainModule.Types.Single(x=>x.Name=="StatusEffect").Methods.Any(x=>x.Name=="GetDuration"&&x.Parameters.Count==0&&x.ReturnType.FullName=="System.Single"),"real elapsed effect timer for countdown");
  var spawner=game.MainModule.Types.Single(x=>x.Name=="SpawnAbility");foreach(var name in new[]{"m_spawnPrefab","m_minToSpawn","m_maxToSpawn","m_setMaxInstancesFromWeaponLevel","m_levelUpSettings","m_spawnDelay","m_preSpawnDelay","m_initialSpawnDelay","m_circleSpawn","m_spawnRadius"})Check(spawner.Fields.Any(x=>x.Name==name),"real batch spawn field "+name);
  var humanoid=game.MainModule.Types.Single(x=>x.Name=="Humanoid");foreach(var name in new[]{"m_seed","m_randomWeapon","m_randomShield","m_randomArmor","m_randomSets","m_randomItems","m_defaultItems"})Check(humanoid.Fields.Any(x=>x.Name==name),"real deterministic native equipment field "+name);
  var fieldOrder=humanoid.Methods.Single(x=>x.Name=="GiveDefaultItems").Body.Instructions.Select(x=>x.Operand).OfType<FieldReference>().Select(x=>x.Name).ToArray();int shieldIndex=Array.LastIndexOf(fieldOrder,"m_randomShield"),weaponIndex=Array.LastIndexOf(fieldOrder,"m_randomWeapon"),armorIndex=Array.LastIndexOf(fieldOrder,"m_randomArmor"),setIndex=Array.LastIndexOf(fieldOrder,"m_randomSets");Check(shieldIndex<weaponIndex&&weaponIndex<armorIndex&&armorIndex<setIndex,"equipment predictor follows actual native shield, weapon, armor, set RNG order");
  Check(humanoid.Methods.Single(x=>x.Name=="Start").Body.Instructions.Select(x=>x.Operand).OfType<MethodReference>().Any(x=>x.Name=="GiveDefaultItems"),"real native equipment generation happens at Start after creation/Awake");
  var spawnLoop=spawner.NestedTypes.SelectMany(x=>x.Methods).Single(x=>x.Name=="MoveNext");var spawnCalls=spawnLoop.Body.Instructions.Select(x=>x.Operand).OfType<MethodReference>().Select(x=>x.Name).ToArray();Check(spawnCalls.Contains("Instantiate")&&spawnCalls.Contains("SetLevel")&&spawnCalls.Contains("Command")&&spawnCalls.Contains("GetSkillLevel"),"native summon coroutine owns creation, skill scaling and follow command");
  foreach(var field in new[]{"m_preSpawnDelay","m_spawnDelay"}){var body=spawnLoop.Body.Instructions;var read=body.First(i=>i.Operand is FieldReference f&&f.Name==field);var branch=read.Next.Next;Check(read.Next.OpCode.Code==Mono.Cecil.Cil.Code.Ldc_R4&&(float)read.Next.Operand==0f&&branch.OpCode.FlowControl==Mono.Cecil.Cil.FlowControl.Cond_Branch&&branch.Operand is Mono.Cecil.Cil.Instruction target&&target.Offset>read.Offset+20,"native zero "+field+" bypasses its per-creature WaitForSeconds and yield");}
  var tame=game.MainModule.Types.Single(x=>x.Name=="Tameable");Check(tame.Methods.Single(x=>x.Name=="RPC_Command").Body.Instructions.Select(x=>x.Operand).OfType<MethodReference>().Any(x=>x.Name=="UnsummonMaxInstances"),"native command enforces max instances after each fresh spawn");Check(tame.Methods.Single(x=>x.Name=="UnsummonMaxInstances").Body.Instructions.Select(x=>x.Operand).OfType<MethodReference>().Any(x=>x.Name=="UnSummon"),"native max instances retires old summons through network unsummon lifecycle");
  var roster=mod.MainModule.Types.Single(x=>x.Name=="SpawnRoster");var rosterCalls=roster.Methods.Where(x=>x.HasBody).SelectMany(x=>x.Body.Instructions).Select(x=>x.Operand).OfType<MethodReference>().ToArray();Check(!rosterCalls.Any(x=>x.Name=="Instantiate"||x.Name=="UseEitr"||x.Name=="UseStamina"||x.Name=="SetHealth"||x.Name=="Heal"),"batch patch never duplicates native creation, charges resources again or heals existing summons");
  var travel=mod.MainModule.Types.Single(x=>x.Name=="Travel");var pinCalls=travel.Methods.Single(x=>x.Name=="Pin").Body.Instructions.Select(x=>x.Operand).OfType<MethodReference>();Check(!pinCalls.Any(x=>x.Name=="Tick"||x.Name=="IsAreaReady"||x.Name=="GetAllCharacters"),"scene removal prefix cannot re-enter readiness or global scan");
  Check(!mod.MainModule.Types.SelectMany(x=>x.Methods).Where(x=>x.HasBody).SelectMany(x=>x.Body.Instructions).Any(x=>x.OpCode.Code==Mono.Cecil.Cil.Code.Stfld&&x.Operand is FieldReference f&&f.DeclaringType.FullName=="Player"),"module never writes native Player teleport state");
  var calls=mod.MainModule.Types.Single(x=>x.Name=="Travel").Methods.Where(x=>x.HasBody).SelectMany(x=>x.Body.Instructions).Select(x=>x.Operand).OfType<MethodReference>().ToArray();Check(!calls.Any(x=>x.DeclaringType.FullName=="UnityEngine.Object"&&x.Name=="Instantiate"),"no duplicate summon path");Check(!calls.Any(x=>x.Name=="SetHealth"||x.Name=="Heal"),"no healing path");Check(!calls.Any(x=>x.Name=="ResetTime"),"travel restoration never renews shield timer");Check(mod.Name.Name=="GhostSummonTravel"&&mod.Name.Version.ToString()==a[2],"production identity");Check(!mod.MainModule.AssemblyReferences.Any(x=>x.Name.Contains("Tests")||x.Name.Contains("Doubles")),"no test assembly dependency");Console.WriteLine("Binary API checks: "+n);
 }
}
